/**
 * Bindings and variables agent email reads. The worker's `Env` extends this interface, so no
 * package function receives the full worker environment.
 */
export interface AgentEmailEnv {
  DATABASE: D1Database;
  KV: KVNamespace;
  BASE_DOMAIN: string;
  CF_API_TOKEN: string;
  CF_ZONE_ID: string;
  CF_API_TIMEOUT_MS?: string;
  DOH_RESOLVER_URL?: string;
  DOH_TIMEOUT_MS?: string;
  // Cloudflare Email Sending binding. Generated by the deploy once configure-agent-email.ts
  // prepared Email Sending; absent means email is off. Present does not mean on: a superadmin
  // turns agent email on (setup-state.ts).
  AGENT_EMAIL?: SendEmail;
  // This Worker's own script name, generated with AGENT_EMAIL; the admin setup points the
  // agent@ Email Routing rule at it.
  AGENT_EMAIL_WORKER_NAME?: string;
}
